import type { ToolRunner } from "@bithumb-official/bithumb-core";
import type { CliValues } from "../parser.js";
import { toNumber, toArray, parsePositiveInt } from "../parser.js";
import { outputLine, errorLine, printJson, printTable, printKv } from "../formatter.js";

export async function handleTwapCommand(
  run: ToolRunner,
  action: string,
  v: CliValues,
  json: boolean,
): Promise<void> {
  switch (action) {
    case "place":
      return cmdPlace(run, v, json);
    case "list":
      return cmdList(run, v, json);
    case "cancel":
      return cmdCancel(run, v, json);
    default:
      errorLine(`Unknown twap command: ${action}. Run 'bithumb twap --help' for usage.`);
      process.exitCode = 1;
  }
}

async function cmdPlace(run: ToolRunner, v: CliValues, json: boolean): Promise<void> {
  if (!v.market || !v.side || !v.duration || !v.frequency) {
    errorLine("Error: --market, --side, --duration, --frequency required.");
    process.exitCode = 1;
    return;
  }
  if (v.side === "bid" && !v.price) {
    errorLine("Error: --price is required for bid.");
    errorLine("Example: bithumb twap place --market KRW-BTC --side bid --duration 3600 --frequency 60 --price 50000000");
    process.exitCode = 1;
    return;
  }
  if (v.side === "ask" && !v.volume) {
    errorLine("Error: --volume is required for ask.");
    errorLine("Example: bithumb twap place --market KRW-BTC --side ask --duration 1800 --frequency 30 --volume 0.5");
    process.exitCode = 1;
    return;
  }
  const args: Record<string, unknown> = {
    market: v.market,
    side: v.side,
    duration: v.duration,
    frequency: v.frequency,
  };
  if (v.price) args.price = v.price;
  if (v.volume) args.volume = v.volume;
  const result = await run("twap_place_order", args);
  const data = result.data as Record<string, unknown>;
  if (json) return printJson(data);
  printKv(data);
}

async function cmdList(run: ToolRunner, v: CliValues, json: boolean): Promise<void> {
  const args: Record<string, unknown> = {};
  if (v.market) args.market = v.market;
  if (v.state) args.state = v.state;
  if (v.orderIds) args.order_ids = toArray(v.orderIds);
  if (v.nextKey) args.next_key = v.nextKey;
  if (v.limit) args.limit = parsePositiveInt("limit", toNumber(v.limit, "limit"));
  if (v.orderBy) args.order_by = v.orderBy;
  const result = await run("twap_get_orders", args);
  // /v1/twap 응답은 envelope: { orders: [...], has_next, next_key }
  const envelope = result.data as
    | { orders?: Record<string, unknown>[]; has_next?: boolean; next_key?: string }
    | undefined;
  const items = envelope?.orders ?? [];
  if (json) return printJson(envelope);
  if (!items.length) { outputLine("No TWAP orders found"); return; }
  // Relabel each row's legacy `uuid` field as `order_id` for display
  // consistency with the input flag. Raw JSON (--json) keeps the original field.
  printTable(items.map((o) => renameKey(o, "uuid", "order_id")));
  // The summary table drops envelope-level fields, so surface the pagination
  // cursor here — without it a table-mode user cannot fetch beyond this page.
  // Hints go to stderr so they don't contaminate piped/redirected table data.
  if (envelope?.has_next) {
    if (envelope.next_key) {
      errorLine(`\nNext page: ${nextPageHint(v, envelope.next_key)}`);
    } else {
      errorLine(
        "\n[warning] has_next is true but next_key is missing. Use --json to inspect the raw response.",
      );
    }
  }
}

// Bithumb's cursor pagination carries no filter context — the cursor alone does
// not re-apply --state/--market/etc. So the next-page hint must re-emit every
// filter/sort/page-size option from the current call (not just the cursor),
// otherwise the suggested command silently widens to an unfiltered query and
// returns rows the user never asked for. Flags are listed in args-declaration
// order with --next-key last ("original query + cursor"). Values are emitted
// unquoted: market/state/order-by are alphanumeric, limit is numeric, order-ids
// is comma-joined UUIDs, and the base64 cursor has no shell-special chars.
function nextPageHint(v: CliValues, nextKey: string): string {
  const parts = ["bithumb twap list"];
  if (v.market) parts.push(`--market ${v.market}`);
  if (v.state) parts.push(`--state ${v.state}`);
  if (v.orderIds) parts.push(`--order-ids ${v.orderIds}`);
  if (v.limit) parts.push(`--limit ${v.limit}`);
  if (v.orderBy) parts.push(`--order-by ${v.orderBy}`);
  parts.push(`--next-key ${nextKey}`);
  return parts.join(" ");
}

// Return a shallow copy of `obj` with key `from` renamed to `to`, preserving
// insertion order. If `from` is absent, returns the object unchanged.
function renameKey(
  obj: Record<string, unknown>,
  from: string,
  to: string,
): Record<string, unknown> {
  if (!(from in obj)) return obj;
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(obj)) {
    out[k === from ? to : k] = v;
  }
  return out;
}

async function cmdCancel(run: ToolRunner, v: CliValues, json: boolean): Promise<void> {
  if (!v.algoOrderId) {
    errorLine("Error: --algo-order-id required. Example: bithumb twap cancel --algo-order-id abc-123");
    process.exitCode = 1;
    return;
  }
  const result = await run("twap_cancel_order", { algo_order_id: v.algoOrderId });
  const data = result.data as Record<string, unknown>;
  if (json) return printJson(data);
  printKv(data);
}
